export const WATCH_TOWER_PAGE_NAME = 'value-creation_watch-tower';
export const WATCH_TOWER_NAVIGATION_TEST_ID = 'watch-tower-container';
export const WATCH_TOWER_MAX_VISIBLE_FILTERS = 4;
export const WATCH_TOWER_MOCK_FILTERS = true;
export const WATCH_TOWER_QUICK_FILTER_FIELDS = [
  'country',
  'watch_tower_brand',
  'kpis',
  'currency',
  'periods',
] as const;

export const WATCH_TOWER_TRAY_ONLY_FIELDS = [
  'region',
  'driver',
  'vehicle_level_1',
  'vehicle_level_2',
  'vehicle_level_3',
  'vehicle_level_4',
  'vehicle_level_5',
  'channel',
] as const;

export const WATCH_TOWER_VISIBLE_FILTER_FIELDS = [
  'zone',
  ...WATCH_TOWER_QUICK_FILTER_FIELDS,
  ...WATCH_TOWER_TRAY_ONLY_FIELDS,
] as const;
